repo_files.minishop/cart.py:
"""A cart combines repeated additions of the same SKU."""

from dataclasses import dataclass


@dataclass(frozen=True)
class CartLine:
    sku: str
    quantity: int


class Cart:
    def __init__(self) -> None:
        self._quantities: dict[str, int] = {}

    def add(self, sku: str, quantity: int = 1) -> None:
        if not sku.strip():
            raise ValueError("sku is required")
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        self._quantities[sku] = self._quantities.get(sku, 0) + quantity

    def remove(self, sku: str) -> None:
        self._quantities.pop(sku, None)

    def lines(self) -> tuple[CartLine, ...]:
        return tuple(CartLine(sku, quantity) for sku, quantity in self._quantities.items())

repo_files.minishop/catalog.py:
"""Product catalog with prices stored as integer cents."""

from dataclasses import dataclass


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price_cents: int
    active: bool = True

    def __post_init__(self) -> None:
        if not self.sku.strip() or not self.name.strip():
            raise ValueError("sku and name are required")
        if self.price_cents < 0:
            raise ValueError("price cannot be negative")


class Catalog:
    def __init__(self, products: list[Product]) -> None:
        self._products: dict[str, Product] = {}
        for product in products:
            if product.sku in self._products:
                raise ValueError("duplicate sku")
            self._products[product.sku] = product

    def purchasable(self, sku: str) -> Product:
        product = self._products.get(sku)
        if product is None or not product.active:
            raise ValueError("product is unavailable")
        return product

repo_files.minishop/checkout.py:
"""Checkout logic that reserves ordered items."""

from minishop.inventory import Inventory


def checkout(inventory: Inventory, sku: str, quantity: int) -> dict[str, int | str]:
    if quantity <= 0:
        raise ValueError("quantity must be positive")
    if inventory.available(sku) <= quantity:
        raise ValueError("not enough stock")
    inventory.reserve(sku, quantity)
    return {"sku": sku, "quantity": quantity}

repo_files.minishop/inventory.py:
"""In-memory stock accounting used by checkout."""


class Inventory:
    def __init__(self, stock: dict[str, int]) -> None:
        if any(quantity < 0 for quantity in stock.values()):
            raise ValueError("stock cannot be negative")
        self._stock = dict(stock)

    def available(self, sku: str) -> int:
        return self._stock.get(sku, 0)

    def snapshot(self) -> dict[str, int]:
        return dict(self._stock)

    def restock(self, sku: str, quantity: int) -> None:
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        self._stock[sku] = self.available(sku) + quantity

    def reserve(self, sku: str, quantity: int) -> None:
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        if self.available(sku) < quantity:
            raise ValueError("not enough stock")
        self._stock[sku] -= quantity

    def reserve_many(self, quantities: dict[str, int]) -> None:
        if any(quantity <= 0 for quantity in quantities.values()):
            raise ValueError("quantity must be positive")
        if any(self.available(sku) < quantity for sku, quantity in quantities.items()):
            raise ValueError("not enough stock")
        for sku, quantity in quantities.items():
            self._stock[sku] -= quantity

repo_files.minishop/pricing.py:
"""Deterministic checkout pricing; all amounts are integer cents."""

from dataclasses import dataclass

from minishop.cart import Cart
from minishop.catalog import Catalog


@dataclass(frozen=True)
class Coupon:
    code: str
    percent_off: int
    minimum_cents: int = 0

    def __post_init__(self) -> None:
        if not self.code.strip() or not 1 <= self.percent_off <= 100:
            raise ValueError("invalid coupon")
        if self.minimum_cents < 0:
            raise ValueError("minimum cannot be negative")


@dataclass(frozen=True)
class Quote:
    subtotal_cents: int
    discount_cents: int
    shipping_cents: int
    total_cents: int


def quote(
    cart: Cart,
    catalog: Catalog,
    coupon: Coupon | None = None,
    *,
    free_shipping_at_cents: int = 5000,
    shipping_cents: int = 500,
) -> Quote:
    if free_shipping_at_cents < 0 or shipping_cents < 0:
        raise ValueError("shipping amounts cannot be negative")
    lines = cart.lines()
    if not lines:
        raise ValueError("cart is empty")
    subtotal = sum(catalog.purchasable(line.sku).price_cents * line.quantity for line in lines)
    discount = 0
    if coupon is not None:
        if subtotal < coupon.minimum_cents:
            raise ValueError("coupon minimum not met")
        discount = subtotal * coupon.percent_off // 100
    shipping = 0 if subtotal >= free_shipping_at_cents else shipping_cents
    return Quote(subtotal, discount, shipping, subtotal - discount + shipping)

